import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {matchingRule,movementResult} from '../core.js';import {matchingPhotographs} from '../photographs.js';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),refs=['126618LN','126715CHNR','126718GRNR'],rules=read('research-updates-20261008.json').filter(r=>refs.includes(r.baseReference)),photos=read('photographs.json').photographs.filter(p=>p.id.startsWith('rolex-')&&p.id.includes('-20261026-')&&refs.some(r=>p.references.includes(r)));
test('Gold Rolex exact mappings distinguish Submariner and GMT calibres',()=>{assert.equal(rules.length,3);for(const [r,c] of [['126618LN','3235'],['126715CHNR','3285'],['126718GRNR','3285']]){const rule=matchingRule(rules,'Rolex',r);assert.equal(movementResult(rule,c).level,'match');assert.equal(movementResult(rule,c==='3235'?'3285':'3235').level,'caution');}for(const r of ['126618LB','126613LN','126711CHNR','126713GRNR','M126718GRNR0001','126715CHNRX'])assert.equal(matchingRule(rules,'Rolex',r),null);});
test('Gold Rolex photographs remain separate by metal bezel and bracelet execution',()=>{assert.equal(photos.length,6);for(const ref of refs){const found=matchingPhotographs(photos,'Rolex',ref);assert.equal(found.length,2);assert.deepEqual(found.map(p=>p.category).sort(),['braceletClasp','front']);assert.ok(found.every(p=>p.matchScope==='representative variant'&&!p.depictsMovement));assert.equal(matchingPhotographs(photos,'Rolex',ref,{externalOnly:true}).length,2);}assert.match(photos.find(p=>p.references.includes('126718GRNR')).variant,/Jubilee/);assert.match(photos.find(p=>p.references.includes('126715CHNR')).variant,/Everose.*Oyster/);for(const ref of ['126618LB','126711CHNR','126713GRNR','126718GRNR0001'])assert.equal(matchingPhotographs(photos,'Rolex',ref).length,0);});
test('Gold Rolex research records retain the obscured caseback and fitted movement gaps',()=>{const source=read('research-queue-gold-rolex-20261026-sources.json');for(const r of source.records){assert.deepEqual(r.unsupported,['movement','caseback','inner caseback']);assert.match(r.conclusion,/not a readable fitted-movement marking/);assert.equal(r.sources.length,2);}});
